# Cockpit ITSM public API - runtime core of the modules generated by CIPAT
# Python 3.8+, standard library only (urllib, json, datetime).
#
# Maintained by hand, embedded in CIPAT and written next to each generated module:
# do not edit a copy, it is replaced when it differs from the generator's version.
"""Runtime core of the Cockpit ITSM API modules generated by CIPAT."""

import datetime
import json
import ssl
import time
import urllib.error
import urllib.parse
import urllib.request
import uuid
from typing import Any, Callable, Dict, List, Optional, Tuple, Union

__all__ = [
    "CockpitItsmError", "CockpitItsmCore",
    "url_encode", "add_query", "query_string",
    "parse_date_time", "parse_date", "format_date_time", "format_date",
    "as_obj", "as_arr", "unquote",
    "to_str", "to_int", "to_float", "to_bool", "to_date_time", "to_date", "to_raw",
    "list_of", "array_of", "put", "put_raw", "from_date_time", "from_date",
]

Json = Any


class CockpitItsmError(Exception):
    """Error answered by the API (non-2xx), or invalid JSON response (status_code 0)."""

    def __init__(self, status_code: int, message: str, response: str = ""):
        super().__init__(message)
        self.status_code = status_code
        self.response = response


def _first_non_empty(*values: Any) -> str:
    for value in values:
        if isinstance(value, str) and value.strip():
            return value.strip()
    return ""


def _error(status: int, response: str) -> CockpitItsmError:
    # Message from errorMessage (API) or error_description / error (OAuth), else start of the response
    detail = ""
    try:
        data = json.loads(response) if response else None
        if isinstance(data, dict):
            detail = _first_non_empty(data.get("errorMessage"), data.get("error_description"), data.get("error"))
    except ValueError:
        pass
    if not detail:
        detail = (response or "").strip()[:300]
    return CockpitItsmError(status, "Cockpit ITSM: HTTP error %d - %s" % (status, detail), response)


class CockpitItsmCore:
    """OAuth token, HTTP calls and paging. The generated class inherits from it.

    saas=True: https://{tenant}.cockpit-itsm.com - saas=False: https://{tenant}
    (an on-premise tenant given with its scheme, e.g. http://host:8080, is used as is).
    """

    def __init__(self, saas: bool = True, tenant: str = "", client_id: str = "", client_secret: str = ""):
        self._saas = saas
        self._tenant = tenant
        self._client_id = client_id
        self._client_secret = client_secret
        self.page_size = 500           # page size of paged lists (API maximum)
        self.timeout = 60.0            # seconds
        self.ssl_context: Optional[ssl.SSLContext] = None
        self.last_status = 0
        self._token = ""
        self._token_expiry = 0.0       # time.time() value

    # ---------------------------------------------------------------- settings (changing them discards the token)

    @property
    def saas(self) -> bool:
        return self._saas

    @saas.setter
    def saas(self, value: bool) -> None:
        self._saas = value
        self.clear_token()

    @property
    def tenant(self) -> str:
        return self._tenant

    @tenant.setter
    def tenant(self, value: str) -> None:
        self._tenant = value
        self.clear_token()

    @property
    def client_id(self) -> str:
        return self._client_id

    @client_id.setter
    def client_id(self, value: str) -> None:
        self._client_id = value
        self.clear_token()

    @property
    def client_secret(self) -> str:
        return self._client_secret

    @client_secret.setter
    def client_secret(self, value: str) -> None:
        self._client_secret = value
        self.clear_token()

    @staticmethod
    def make_base_url(saas: bool, tenant: str) -> str:
        result = (tenant or "").strip().rstrip("/")
        if saas:
            return "https://" + result + ".cockpit-itsm.com"
        return result if "://" in result else "https://" + result

    @property
    def base_url(self) -> str:
        return self.make_base_url(self._saas, self._tenant)

    # ---------------------------------------------------------------- token

    @property
    def access_token(self) -> str:
        return self._token

    @property
    def token_expiry(self) -> float:
        """Expiry of the token (time.time() value), 60 s before the server's one."""
        return self._token_expiry

    def is_token_valid(self) -> bool:
        return bool(self._token) and time.time() < self._token_expiry

    def clear_token(self) -> None:
        self._token = ""
        self._token_expiry = 0.0

    def set_token(self, token: str, expiry: float) -> None:
        """Token obtained elsewhere (shared between instances), expiry = time.time() value."""
        self._token = token
        self._token_expiry = expiry

    def authenticate(self) -> None:
        """POST /oauth2/token (multipart/form-data, client credentials, scope public-api)."""
        boundary = "----CockpitItsm" + uuid.uuid4().hex
        fields = [("grant_type", "client_credentials"), ("client_id", self._client_id),
                  ("client_secret", self._client_secret), ("scope", "public-api")]
        body = "".join('--%s\r\nContent-Disposition: form-data; name="%s"\r\n\r\n%s\r\n' % (boundary, n, v)
                       for n, v in fields) + "--%s--\r\n" % boundary
        status, text = self._send("POST", self.base_url + "/oauth2/token", body.encode("utf-8"),
                                  "multipart/form-data; boundary=" + boundary, False)
        if status < 200 or status > 299:
            raise _error(status, text)
        data = self._parse(text)
        token = data.get("access_token") if isinstance(data, dict) else None
        if not token:
            raise CockpitItsmError(status, "Cockpit ITSM: no access_token in the response", text)
        expires_in = to_int(data.get("expires_in")) or 3600
        self._token = token
        self._token_expiry = time.time() + max(expires_in - 60, 0)

    # ---------------------------------------------------------------- calls

    def _send(self, method: str, url: str, data: Optional[bytes], content_type: str,
              with_token: bool) -> Tuple[int, str]:
        request = urllib.request.Request(url, data=data, method=method)
        request.add_header("Accept", "application/json")
        if content_type:
            request.add_header("Content-Type", content_type)
        if with_token:
            request.add_header("Authorization", "Bearer " + self._token)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout, context=self.ssl_context) as response:
                status = response.status
                raw = response.read()
        except urllib.error.HTTPError as e:
            status = e.code
            raw = e.read() or b""
        self.last_status = status
        return status, raw.decode("utf-8", errors="replace")

    def call(self, method: str, path_query: str, body: Union[str, dict, list, None] = None) -> str:
        """Raw response of METHOD path_query (e.g. "/api/end-users/12").

        body: text sent as is, or dict / list sent as JSON. POST, PUT and PATCH always send a body.
        The token is requested when needed, and once more when the API answers 401.
        """
        if body is None:
            data = b"" if method.upper() in ("POST", "PUT", "PATCH") else None
        elif isinstance(body, str):
            data = body.encode("utf-8")
        else:
            data = json.dumps(body, ensure_ascii=False).encode("utf-8")
        content_type = "application/json; charset=utf-8" if data is not None else ""
        if not self.is_token_valid():
            self.authenticate()
        status, text = self._send(method, self.base_url + path_query, data, content_type, True)
        if status == 401:
            self.authenticate()
            status, text = self._send(method, self.base_url + path_query, data, content_type, True)
        if status < 200 or status > 299:
            raise _error(status, text)
        return text

    @staticmethod
    def _parse(text: str) -> Json:
        if text is None or not text.strip():
            return None
        try:
            return json.loads(text)
        except ValueError as e:
            raise CockpitItsmError(0, "Invalid JSON response: %s" % e, text)

    def call_json(self, method: str, path_query: str, body: Union[str, dict, list, None] = None) -> Json:
        """Parsed JSON response (dict, list, value), None for an empty response."""
        return self._parse(self.call(method, path_query, body))

    def fetch_all_pages(self, method: str, path_query: str, body: Optional[dict], page_path: str) -> list:
        """Items ("content") of every page of a paged list.

        page_path: dotted path of the {page, pageSize} object in the body ("" = the body itself).
        """
        body = dict(body) if body else {}
        page_obj = body
        if page_path:
            for name in page_path.split("."):
                child = page_obj.get(name)
                if not isinstance(child, dict):
                    child = {}
                else:
                    child = dict(child)
                page_obj[name] = child
                page_obj = child
        result: list = []
        page = 0
        total_pages = -1
        total_items = -1
        while True:
            page_obj["page"] = page
            page_obj["pageSize"] = self.page_size
            data = self.call_json(method, path_query, body)
            if not isinstance(data, dict):
                break
            if page == 0:
                pages = to_int(data.get("totalNumberOfPages"))
                items = to_int(data.get("totalNumberOfElements"))
                total_pages = -1 if pages is None else pages
                total_items = -1 if items is None else items
            content = data.get("content")
            if not isinstance(content, list) or not content:
                break
            result.extend(content)
            page += 1
            if total_pages >= 0 and page >= total_pages:
                break
        if 0 <= total_items < len(result):
            del result[total_items:]
        return result


# -------------------------------------------------------------------- URL

def url_encode(value: Any) -> str:
    return urllib.parse.quote(str(value), safe="")


def _query_text(value: Any) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, datetime.datetime):
        return format_date_time(value)
    if isinstance(value, datetime.date):
        return format_date(value)
    if isinstance(value, float):
        return repr(value)
    return str(value)


def add_query(query: List[Tuple[str, str]], name: str, value: Any) -> None:
    """Query parameter; None is not sent, a list is sent as repeated keys."""
    if value is None:
        return
    if isinstance(value, (list, tuple)):
        for item in value:
            add_query(query, name, item)
        return
    query.append((name, _query_text(value)))


def query_string(query: List[Tuple[str, str]]) -> str:
    """"" or "?a=1&b=2" (values encoded as %20, not +)."""
    if not query:
        return ""
    return "?" + "&".join(url_encode(n) + "=" + url_encode(v) for n, v in query)


# -------------------------------------------------------------------- dates

def parse_date_time(value: Optional[str]) -> Optional[datetime.datetime]:
    """yyyy-mm-dd[Thh:nn[:ss[.fff]]][Z|+hh[:]mm] -> aware datetime in UTC (None if invalid)."""
    if not value or not isinstance(value, str):
        return None
    s = value.strip()
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    # +0000 -> +00:00
    if len(s) > 5 and s[-5] in "+-" and s[-4:].isdigit() and "T" in s:
        s = s[:-2] + ":" + s[-2:]
    # fractions other than 3 or 6 digits (fromisoformat of Python < 3.11)
    if "." in s:
        head, _, tail = s.partition(".")
        digits = ""
        while tail and tail[0].isdigit():
            digits, tail = digits + tail[0], tail[1:]
        s = head + "." + (digits + "000000")[:6] + tail
    try:
        result = datetime.datetime.fromisoformat(s)
    except ValueError:
        try:
            result = datetime.datetime.combine(datetime.date.fromisoformat(s[:10]), datetime.time())
        except ValueError:
            return None
    if result.tzinfo is None:
        result = result.replace(tzinfo=datetime.timezone.utc)
    return result.astimezone(datetime.timezone.utc)


def parse_date(value: Optional[str]) -> Optional[datetime.date]:
    if not value or not isinstance(value, str):
        return None
    try:
        return datetime.date.fromisoformat(value.strip()[:10])
    except ValueError:
        return None


def format_date_time(value: datetime.datetime) -> str:
    """UTC, yyyy-mm-ddThh:nn:ss.zzzZ (a naive datetime is taken as local time)."""
    if value.tzinfo is None:
        value = value.astimezone()
    value = value.astimezone(datetime.timezone.utc)
    return value.strftime("%Y-%m-%dT%H:%M:%S.") + "%03dZ" % (value.microsecond // 1000)


def format_date(value: datetime.date) -> str:
    if isinstance(value, datetime.datetime):
        value = value.date()
    return value.strftime("%Y-%m-%d")


# -------------------------------------------------------------------- JSON: reading (None if missing, null or invalid)

def as_obj(value: Any) -> Optional[dict]:
    return value if isinstance(value, dict) else None


def as_arr(value: Any) -> Optional[list]:
    return value if isinstance(value, list) else None


def unquote(text: Optional[str]) -> Optional[str]:
    """Text of a JSON string response ("abc" -> abc), other text unchanged."""
    if text is None:
        return None
    s = text.strip()
    if len(s) >= 2 and s.startswith('"') and s.endswith('"'):
        try:
            value = json.loads(s)
            if isinstance(value, str):
                return value
        except ValueError:
            pass
    return text


def to_str(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False)
    return str(value)


def to_int(value: Any) -> Optional[int]:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    if isinstance(value, str):
        try:
            return int(value.strip())
        except ValueError:
            try:
                return int(float(value.strip()))
            except ValueError:
                return None
    return None


def to_float(value: Any) -> Optional[float]:
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except ValueError:
            return None
    return None


def to_bool(value: Any) -> Optional[bool]:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() == "true"
    if isinstance(value, (int, float)):
        return value != 0
    return None


def to_date_time(value: Any) -> Optional[datetime.datetime]:
    return parse_date_time(value) if isinstance(value, str) else None


def to_date(value: Any) -> Optional[datetime.date]:
    return parse_date(value) if isinstance(value, str) else None


def to_raw(value: Any) -> Optional[str]:
    """JSON text of a value (raw members)."""
    if value is None:
        return None
    return json.dumps(value, ensure_ascii=False)


def list_of(arr: Any, conv: Callable[[Any], Any]) -> Optional[list]:
    """Converted items of a JSON array; None if the array is missing."""
    if not isinstance(arr, list):
        return None
    return [conv(v) for v in arr]


# -------------------------------------------------------------------- JSON: writing (None values are not written)

def array_of(items: Optional[list], conv: Optional[Callable[[Any], Any]] = None) -> list:
    """JSON array of the converted items of a list (None items kept as null)."""
    if not items:
        return []
    return [None if v is None else (conv(v) if conv else v) for v in items]


def from_date_time(value: Optional[datetime.datetime]) -> Optional[str]:
    return None if value is None else format_date_time(value)


def from_date(value: Optional[datetime.date]) -> Optional[str]:
    return None if value is None else format_date(value)


def put(obj: Dict[str, Any], name: str, value: Any) -> None:
    if value is None:
        return
    if isinstance(value, datetime.datetime):
        obj[name] = format_date_time(value)
    elif isinstance(value, datetime.date):
        obj[name] = format_date(value)
    else:
        obj[name] = value


def put_raw(obj: Dict[str, Any], name: str, text: Optional[str]) -> None:
    """Raw member: JSON text inserted as a value."""
    if text is None or not text.strip():
        return
    obj[name] = json.loads(text)
